policy:
// No admin paths on GitHub.
@id("no_admin") forbid (principal, action == Box::Action::"http:request", resource) when { context.input.host == "api.github.com" && context.input.path like "/admin/*" };

@id("spawn_uname") permit (principal, action == Box::Action::"shell:spawn", resource) when { context.input.program_path == "/usr/bin/uname" && context.input.program == "uname" };

@id("route_auth_connect") permit (principal, action == Box::Action::"net:connect", resource) when { (context.input.host == "login.example.com" && context.input.port == 443) || (context.input.host == "auth.example.com" && context.input.port == 8443) };
@id("route_auth_request") permit (principal, action == Box::Action::"http:request", resource) when { context.input.host == "login.example.com" || context.input.host == "auth.example.com" };
@id("route_github_connect") permit (principal, action == Box::Action::"net:connect", resource) when { (context.input.host == "api.github.com" && context.input.port == 443) };
@id("route_github_request") permit (principal, action == Box::Action::"http:request", resource) when { context.input.host == "api.github.com" };
@id("route_keyed_connect") permit (principal, action == Box::Action::"net:connect", resource) when { (context.input.host == "k.example.com" && context.input.port == 8443) };
@id("route_keyed_request") permit (principal, action == Box::Action::"http:request", resource) when { context.input.host == "k.example.com" };
@id("box_home_write") forbid (principal, action == Box::Action::"fs:write", resource) when { (context.input.path == "~/.box" || context.input.path like "~/.box/*") };
@id("box_home_delete") forbid (principal, action == Box::Action::"fs:delete", resource) when { (context.input.path == "~/.box" || context.input.path like "~/.box/*") };
@id("box_home_move") forbid (principal, action == Box::Action::"fs:move", resource) when { (context.input.path == "~/.box" || context.input.path like "~/.box/*") };

@id("project_configuration_write") forbid (principal, action == Box::Action::"fs:write", resource) when { context.input.path == "/private/tmp/acbox/demo/.box" || context.input.path like "/private/tmp/acbox/demo/.box/*" };
@id("project_configuration_delete") forbid (principal, action == Box::Action::"fs:delete", resource) when { context.input.path == "/private/tmp/acbox/demo/.box" || context.input.path like "/private/tmp/acbox/demo/.box/*" };
@id("project_configuration_move") forbid (principal, action == Box::Action::"fs:move", resource) when { context.input.path == "/private/tmp/acbox/demo/.box" || context.input.path like "/private/tmp/acbox/demo/.box/*" };
